'use client';
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { auth } from '../../firebase';
import { signOut } from 'firebase/auth';
import './profile.css';

export default function ProfilePage() {
  const [userStats, setUserStats] = useState({
    totalQuizzes: 0,
    averageScore: 0,
    quizHistory: []
  });
  const router = useRouter();

  useEffect(() => {
    // Load user stats from localStorage
    const savedStats = localStorage.getItem('userQuizStats');
    if (savedStats) {
      setUserStats(JSON.parse(savedStats));
    }
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      router.push('/login');
    } catch (err) {
      console.error('Logout failed', err);
    }
  };

  const getScoreColor = (percentage) => {
    if (percentage >= 80) return '#2ecc71';
    if (percentage >= 60) return '#f39c12';
    return '#e74c3c';
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  return (
    <div className="profile-container">
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo">
            <h1>BingeQuiz</h1>
          </div>
          <div className="user-actions">
            <Link href="/home" className="back-button">Back to Home</Link>
            <button onClick={handleLogout} className="logout-button">Logout</button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="main-content">
        {/* Profile Header */}
        <section className="profile-header">
          <h1>Your Profile</h1>
          <p>Track your movie quiz journey and see how you're improving!</p>
        </section>

        {/* Stats Overview */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-number">{userStats.totalQuizzes}</span>
            <span className="stat-label">Total Quizzes</span>
          </div>
          <div className="stat-card">
            <span className="stat-number">{userStats.averageScore.toFixed(1)}%</span>
            <span className="stat-label">Average Score</span>
          </div>
          <div className="stat-card">
            <span className="stat-number">{userStats.quizHistory.length}</span>
            <span className="stat-label">Movies Completed</span>
          </div>
        </div>

        {/* Quiz History */}
        <section className="quiz-history">
          <h2>Quiz History</h2>
          {userStats.quizHistory.length === 0 ? (
            <div className="empty-state">
              <p>No quizzes completed yet!</p>
              <Link href="/home" className="start-quiz-button">Take Your First Quiz</Link>
            </div>
          ) : (
            <div className="history-list">
              {userStats.quizHistory.map((quiz, index) => (
                <div key={index} className="history-item">
                  <div className="quiz-info">
                    <h3 className="movie-title">{quiz.movie}</h3>
                    <p className="quiz-date">{formatDate(quiz.date)}</p>
                  </div>
                  <div className="quiz-score">
                    <span 
                      className="score-text"
                      style={{ color: getScoreColor(quiz.percentage) }}
                    >
                      {quiz.score}/{quiz.total}
                    </span>
                    <span className="score-percentage">
                      {quiz.percentage}%
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}